#!/usr/bin/env bash
# Generated by the CLAUDE.md customization prompt.
# Stop hook: blocks Claude from finishing while the verify command fails.
input="$(cat)"

# Claude was already sent back once by this hook. Let it stop and report instead of looping.
if echo "$input" | grep -Eq '"stop_hook_active"[[:space:]]*:[[:space:]]*true'; then
  exit 0
fi

cd "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null || exit 0

# Nothing changed in the working tree (or not a git repo): nothing to verify.
[ -z "$(git status --porcelain 2>/dev/null)" ] && exit 0

# Pick how to run the verify command (CLAUDE.md: do not bypass the Nix dev shell).
if [ -z "${IN_NIX_SHELL:-}" ] && command -v nix >/dev/null 2>&1; then
  verify=(nix develop -c bash -c 'cargo build && cargo test')
elif command -v pkg-config >/dev/null 2>&1 && pkg-config --exists gtk4; then
  verify=(bash -c 'cargo build && cargo test')
else
  echo "skipping verify: GTK4 dev libraries not found; Up builds on Linux only" >&2
  exit 0
fi

output="$( { "${verify[@]}"; } 2>&1)"
status=$?

if [ "$status" -ne 0 ]; then
  {
    echo "Verification failed (exit $status). Fix the failures, then re-run:"
    echo "  cargo build && cargo test"
    echo "----"
    echo "$output" | tail -n 60
  } >&2
  exit 2
fi
exit 0
